import { MD5 } from 'crypto-js'

export function md5ProductViewPwd(admin, pwd) {
  return MD5(`${pwd}_${admin}`).toString()
}

export function encryptProductId(productId) {
  return ((productId * 2) + 5).toString()
}

export function fileToDataURL(file, fn) {
  const reader = new FileReader()
  reader.onloadend = (e) => {
    fn(e.target.result)
  }
  reader.readAsDataURL(file)
}

export function dataURLtoImage(dataUrl, fn) {
  const img = new Image()
  img.onload = function () {
    fn(img)
  }
  img.src = dataUrl
}

export function validateURL(url) {
  return /[a-zA-z]+:\/\/[^\s]*/.test(url)
}

export function validateVideoURL(url) {
  if (!validateURL(url)) {
    return false
  }
  return url.indexOf('.m3u8') !== -1 || url.indexOf('.mp4') !== -1 || url.indexOf('.flv') !== -1
  // const parseData = url.split('.')

  // return ['mp4', 'flv', 'm3u8'].includes(parseData[parseData.length - 1])
}

export function isMobile() {
  return navigator.userAgent.match(
    /(phone|pad|pod|iPhone|iPod|ios|iPad|Android|Mobile|BlackBerry|IEMobile|MQQBrowser|JUC|Fennec|wOSBrowser|BrowserNG|WebOS|Symbian|Windows Phone)/i
  )
}
export function isAndroid() {
  return navigator.userAgent.indexOf('Android') > -1 || navigator.userAgent.indexOf('Adr') > -1
}

export function isIOS() {
  const u = navigator.userAgent
  return !!u.match(/\(i[^;]+;( U;)? CPU.+Mac OS X/)
}

export function isWeChat() {
  var ua = navigator.userAgent.toLowerCase()
  return  ua.indexOf('micromessenger') != -1
}
export function isSafari() {
  const ua = navigator.userAgent.toLowerCase()
  return  /safari/.test(ua) && !/chrome/.test(ua) && !/edg/.test(ua)
}


export function judgeBrand() {
  var sUserAgent = navigator.userAgent.toLowerCase()
  var isIphone = sUserAgent.match(/iphone/i) == 'iphone'
  var isHuawei = sUserAgent.match(/huawei/i) == 'huawei'
  var isHonor = sUserAgent.match(/honor/i) == 'honor'
  var isOppo = sUserAgent.match(/oppo/i) == 'oppo'
  var isOppoR15 = sUserAgent.match(/pacm00/i) == 'pacm00'
  var isVivo = sUserAgent.match(/vivo/i) == 'vivo'
  var isXiaomi = sUserAgent.match(/mi\s/i) == 'mi '
  var isXiaomi2s = sUserAgent.match(/mix\s/i) == 'mix '
  var isRedmi = sUserAgent.match(/redmi/i) == 'redmi'
  var isSamsung = sUserAgent.match(/sm-/i) == 'sm-'

  if (isIphone) {
      return 'iphone'
  } else if (isHuawei || isHonor) {
      return 'huawei'
  } else if (isOppo || isOppoR15) {
      return 'oppo'
  } else if (isVivo) {
      return 'vivo'
  } else if (isXiaomi || isRedmi || isXiaomi2s) {
      return 'xiaomi'
  } else if (isSamsung) {
      return 'samsung'
  } else {
      return 'default'
  }
}

export function validateObjFields(obj, fields) {
  const keyLength = Object.keys(fields).length
  let count = 0
  for (let key in fields) {
    if (key in obj) {
      obj[key] = fields[key]
      count++
    }
  }
  console.log('keyLength:', keyLength, count)
  if (keyLength !== count) {
    throw {
      code: -1,
      message: '数据类型错误',
    }
  }
}

export function getRouteUrl(route) {
  const hostname = `${location.protocol}//${location.host}`
  const firstSlashIndex = route.indexOf('/')
  if (firstSlashIndex === 0) {
    route  = route.slice(firstSlashIndex + 1)
  }
  
  return `${hostname}/${route}`
}


export function isHexUUID(hexUUID) {
  const cleanedUUID = hexUUID.replace(/[ -]/g, '')
  // 将十六进制 UUID 转换为标准格式
  const uuid = cleanedUUID.replace(
    /^([\da-f]{8})([\da-f]{4})([\da-f]{4})([\da-f]{4})([\da-f]{12})$/i,
    '$1-$2-$3-$4-$5'
  )

  // 验证 UUID 是否符合标准格式
  const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i
  return uuidRegex.test(uuid)
}

export function isValidJWT(token) {
  const jwtRegex = /^[A-Za-z0-9-_]+\.[A-Za-z0-9-_]+\.[A-Za-z0-9-_.+/=]*$/
  return jwtRegex.test(token)
}

export function convertCoordinatesToYawPitch(x, y, width, height) {
  // 将 x 和 y 从 [0, width] 和 [0, height] 映射到 [-1, 1]
  let normalizedX = (x / width) * 2 - 1  // 映射到 [-1, 1]
  let normalizedY = 1 - (y / height) * 2  // 映射到 [1, -1]

  // 将 x 坐标映射到 yaw（水平旋转），范围 [-180, 180] 度
  let yaw = normalizedX * 180

  // 将 y 坐标映射到 pitch（垂直旋转），范围 [-90, 90] 度
  let pitch = normalizedY * 90

  return { yaw: yaw, pitch: pitch }
}