import request from '@/utils/request'

export function getProducts(query) {
  return request({
    url: '/product/index',
    method: 'get',
    params: query,
  })
}

export function createProduct(data) {
  return request({
    url: '/product/create',
    method: 'post',
    data,
  })
}

/**
 * 更新作品信息
 * @param {*} id 
 * @param {*} data 
 * @returns 
 */
export function updateProduct(id, data) {
  return request({
    url: `/product/${id}`,
    method: 'put',
    data,
  })
}

/**
 * 删除作品
 * @param {*} sceneId 
 * @returns 
 */
export function deleteProduct(id) {
  return request({
    url: `/product/${id}`,
    method: 'delete'
  })
}

