import Vue from 'vue'
import store from '@/store'
import settings from '@/settings'
import NProgress from 'nprogress' // progress bar
import 'nprogress/nprogress.css' // progress bar style
import VueRouter from 'vue-router'
import HomeView from '../views/home.vue'
import { getToken } from '@/utils/auth' // get token from cookie
import { openLoginDialog } from '@/components/dialog/openLoginHandler'
const whiteList = ['/login', '/auth-redirect', '/register', 'VR', 'VRShare',  '404-route', '/403', '/404', '/500']

// eslint-disable-next-line no-unused-vars
const noAuthRouteNames = [
  'VR',
  'VRShare',
  '403',
  '404',
  '500',
  '404-route',
]
// const originalPush = VueRouter.prototype.push
// VueRouter.prototype.push = function push(location) {
//   return originalPush.call(this, location).catch((err) => err)
// }
Vue.use(VueRouter)
const routes = [
  {
    path: '/',
    name: 'home',
    component: HomeView,
    meta: {
      title: '创作中心',
      keepAlive: false
    }
  },
  {
    path: '/diy/:id',
    name: 'diy',
    component: () => import('../views/diy/index.vue'),
    meta: {
      title: '装修工作站',
    },
  },
  // {
  //   path: '/photoSphereViewer',
  //   name: 'photoSphereViewer',
  //   // route level code-splitting
  //   // this generates a separate chunk (about.[hash].js) for this route
  //   // which is lazy-loaded when the route is visited.
  //   component: () =>
  //     import(/* webpackChunkName: "about" */ '../views/photoSphereViewer.vue'),
  //   meta: {
  //     title: 'photoSphereViewer',
  //     keepAlive: true
  //   },
  // },
  {
    path: '/view/:id',
    name: 'VRView',
    component: () => import('../views/preview/index.vue'),
    meta: {
      title: '作品详情',
      keepAlive: true
    },
  },
  {
    path: '/vr/:id',
    name: 'VR',
    component: () => import('../views/preview/index.vue'),
    meta: {
      title: '作品查看',
      keepAlive: true
    },
  },
  {
    path: '/share/:token',
    name: 'VRShare',
    component: () => import('../views/preview/index.vue'),
    meta: {
      title: '分享作品详情',
      keepAlive: true
    },
  },
  {
    path: '/vip/info',
    name: 'VrVIPInfo',
    component: () => import('../views/vip/info.vue')
  },
  {
    path: '/vip/products',
    name: 'VrVIPProduct',
    component: () => import('../views/vip/product/index.vue')
  },
  {
    path: '/403',
    name: '403',
    component: () => import('@/views/error-page/403'),
    meta: {
      title: '403 Forbidden',
    },
  },
  {
    path: '/404',
    name: '404',
    component: () => import('@/views/error-page/404'),
    meta: {
      title: '404 Not Found',
    },
  },
  {
    path: '/500',
    name: '500',
    component: () => import('@/views/error-page/500'),
    meta: {
      title: '服务器内部错误',
    },
  },
  {
    path: '*',
    name: '404-route',
    component: () => import('@/views/error-page/404')
  }
]
const createRouter = () =>
  new VueRouter({
    mode: 'history', // require service support
    scrollBehavior: () => ({ y: 0 }),
    routes: routes,
  })
const router = createRouter()

function getPageTitle(pageTitle, defaultTitle = null) {
  let title = settings.title
  if (defaultTitle) {
    title = defaultTitle
  }
  if (pageTitle) {
    return `${pageTitle} - ${title}`
  }
  return `${title}`
}

export function resetRouter() {
  const newRouter = createRouter()
  router.matcher = newRouter.matcher // reset router
}

// events
router.beforeEach(async (to, from, next) => {
  if (!noAuthRouteNames.includes(to.name) && to.name !== null) {
    // console.log('对不起，您必须登录')
    store.dispatch('user/getCurrentUser')
  }

  const needKeepAlive = to.meta.keepAlive !== undefined ? to.meta.keepAlive : true
  if (!needKeepAlive) {
    // 如果不需要缓存，则将之前设置的缓存状态排除
    to.matched.forEach(route => {
      if (route.components.default && route.components.default.options) {
        route.components.default.options.keepAlive = false
      }
    })
  }

  NProgress.start()
  document.title = getPageTitle(to.meta.title)
  if (to.matched.length === 0) {
    next('*') // 将路由重定向到 404 组件
  } else {
    const token = getToken()
    if (token) {
      if (to.path === '/login') {
        next({ path: '/' })
        NProgress.done()
      } else {
        next()
        NProgress.done()
      }
    } else {
      if (whiteList.indexOf(to.path) !== -1 || whiteList.indexOf(to.name) !== -1) {
        // in the free login whitelist, go directly
        next()
        NProgress.done()
      } else {
        // other pages that do not have permission to access are redirected to the login page.
        // next(`/login?redirect=${to.path}`)
        NProgress.done()
        openLoginDialog(store.getters.systemTitle, 'login', {
          onSubmit() {
            console.log('点了确定按钮')
          },
          onCancel() {
            console.log('点了取消按钮')
          },
        })
      }
    }
  }

})

router.afterEach(() => {
  NProgress.done()
})

export default router
