const contextMenu = {
    bind(el, { value }) {
      el.addEventListener('contextmenu', value)
    },
    // 当传进来的值更新的时候触发
    componentUpdated(el, { value }) {
      el.$value = value
    },
    // 指令与元素解绑的时候，移除事件绑定
    unbind(el, { value }) {
    //   el.removeEventListener('click', el.handler)
      el.removeEventListener('contextmenu', value)
    },
  }
  
  export default contextMenu
  